SELECT json_build_object('policies',(SELECT json_agg(p ORDER BY tablename,policyname) FROM pg_policies p WHERE schemaname='public' AND tablename IN ('listings','viewings')),'schemas',(SELECT json_agg(json_build_object('name',nspname,'owner',pg_get_userbyid(nspowner),'acl',nspacl) ORDER BY nspname) FROM pg_namespace WHERE nspname IN ('public','private')),'helper',(SELECT json_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definition',pg_get_functiondef(oid)) FROM pg_proc WHERE oid=to_regprocedure('private.can_request_viewing_for_listing(uuid,uuid)')),'tables',(SELECT json_agg(json_build_object('table',c.relname,'acl',c.relacl,'columns',(SELECT json_agg(json_build_object('name',attname,'acl',attacl) ORDER BY attnum) FROM pg_attribute WHERE attrelid=c.oid AND attnum>0 AND NOT attisdropped)) ORDER BY c.relname) FROM pg_class c WHERE c.oid IN ('public.listings'::regclass,'public.viewings'::regclass)));